def check_L(L):
    # L is the final integer we are testing.
    # We use the constraints derived from W2/W4 notation:
    # M = floor(88/L)
    # K = floor(88 * M / L)
    # Check if L = floor(88 * K / L)

    if L <= 0:
        return False, None

    M = int(88 / L)
    K = int(88 * M / L)
    L_calculated = int(88 * K / L)

    is_solution = (L == L_calculated)
    return is_solution, {'L': L, 'M': M, 'K': K, 'L_calculated': L_calculated}

test_Ls = [27, 26, 25]
results = {}
for L in test_Ls:
    results[L] = check_L(L)

for L, (is_solution, data) in results.items():
    print(f"L={L}: Is Solution? {is_solution}")
    print(f"  M = {data['M']}, K = {data['K']}, L_calculated = {data['L_calculated']}")
